265	    @Override
266	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner != null) {
