309	
310	    /**
311	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
312	     * offending field is collected so the caller learns exactly which values must be supplied.
313	     *
314	     * @param ownerFieldsDto the submitted owner payload
315	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
316	     *         telephone is missing or blank
317	     */
318	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
319	        List<String> missingFields = new ArrayList<>();
320	        if (isBlank(ownerFieldsDto.getFirstName())) {
321	            missingFields.add("firstName");
322	        }
323	        if (isBlank(ownerFieldsDto.getLastName())) {
324	            missingFields.add("lastName");
325	        }
326	        if (isBlank(ownerFieldsDto.getAddressLine1())
327	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
328	            missingFields.add("address");
329	        }
330	        if (isBlank(ownerFieldsDto.getCity())) {
331	            missingFields.add("city");
332	        }
333	        if (isBlank(ownerFieldsDto.getTelephone())) {
334	            missingFields.add("telephone");
335	        }
336	        if (!missingFields.isEmpty()) {
337	            throw new MissingOwnerFieldsException(missingFields);
338	        }
339	    }
340	
341	    private boolean isBlank(String value) {
342	        return value == null || value.isBlank();
343	    }
344	
345	    /**
346	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
347	     * current date. A registration date may not lie in the future; a value equal to today or in the
348	     * past is accepted, and an absent date is left to default to the server date.
349	     *
350	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
351	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
352	     */
353	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
354	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
355	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
356	        }
357	    }
358	
359	    /**
360	     * Counts the existing owners who, before this create, already share the given first and last name.
361	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
362	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
363	     * case or spacing still count as the same name.
364	     *
365	     * @param firstName the first name of the owner being created
366	     * @param lastName the last name of the owner being created
