408	    /**
409	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
410	     * forward, and a date that lands on a listed public holiday is likewise rolled forward, until the
411	     * result is a weekday that is not a public holiday; a weekday that is not a holiday is returned
412	     * unchanged. This applies whether the date was supplied on the request or defaulted to the
413	     * server's current date.
414	     *
415	     * @param date the effective registration date (supplied or defaulted)
416	     * @return the first non-holiday weekday on or after the supplied date
417	     */
418	    /**
419	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
420	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
421	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
422	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
423	     *
424	     * @return {@code true} when more than the threshold number of owners are already registered on
425	     *         today's business day, otherwise {@code false}
426	     */
427	    private boolean isBulkSignupWarningActive() {
428	        LocalDate today = toBusinessDay(LocalDate.now());
429	        long ownersToday = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> today.equals(existing.getRegistrationDate()))
431	            .count();
432	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
433	    }
