435	    private LocalDate toBusinessDay(LocalDate date) {
436	        LocalDate adjusted = switch (date.getDayOfWeek()) {
437	            case SATURDAY -> date.plusDays(2);
438	            case SUNDAY -> date.plusDays(1);
439	            default -> date;
440	        };
441	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
442	            adjusted = adjusted.plusDays(1);
443	        }
444	        return adjusted;
445	    }
446	
447	    private boolean isWeekend(LocalDate date) {
448	        return switch (date.getDayOfWeek()) {
449	            case SATURDAY, SUNDAY -> true;
450	            default -> false;
451	        };
452	    }
