464	    /**
465	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
466	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
467	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
468	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
469	     * to the same base code only when they share a region and produce the same telephone-and-last-name
470	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
471	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
472	     *
473	     * @param postcode the owner's postcode, used first to derive the region
474	     * @param city the owner's city, used to derive the region when the postcode maps to none
475	     * @param normalizedTelephone the owner's normalized (E.164) telephone
476	     * @param lastName the owner's last name
477	     * @return the formatted, de-duplicated customer code
478	     */
479	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
480	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
481	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
482	        String baseCode = region + "-" + hash8;
483	        return deduplicateCustomerCode(baseCode);
484	    }
