486	    /**
487	     * De-duplicates a computed customer code against every existing owner's customer code. When no
488	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
489	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
490	     *
491	     * @param baseCode the computed, formatted customer code before de-duplication
492	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
493	     */
494	    private String deduplicateCustomerCode(String baseCode) {
495	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
496	            .map(Owner::getCustomerCode)
497	            .filter(java.util.Objects::nonNull)
498	            .collect(java.util.stream.Collectors.toSet());
499	        if (!existingCodes.contains(baseCode)) {
500	            return baseCode;
501	        }
502	        int n = 2;
503	        while (existingCodes.contains(baseCode + "-" + n)) {
504	            n++;
505	        }
506	        return baseCode + "-" + n;
507	    }
