524	    /**
525	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
526	     * country calling code. Australia ('+61') uses 9 national digits and the North American
527	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
528	     * E.164 length (8 to 15 digits overall).
529	     */
530	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
531	        java.util.Map.of("61", 9, "1", 10);
532	
533	    /**
534	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
535	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
536	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
537	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
538	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
539	     * E.164 string is what gets stored and returned.
540	     *
541	     * @param telephone the raw telephone value from the request
542	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
543	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
544	     *         national number has the wrong length for its country code
545	     */
546	    private String normalizeTelephone(String telephone) {
547	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
548	        String e164;
549	        if (cleaned.startsWith("+")) {
550	            e164 = cleaned;
551	        } else {
552	            String national = cleaned;
553	            if (national.startsWith("0")) {
554	                national = national.substring(1);
555	            }
556	            e164 = "+61" + national;
557	        }
558	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
559	            throw new InvalidOwnerFieldsException(List.of("telephone"));
560	        }
561	        validateNationalNumberLength(e164);
562	        return e164;
563	    }
564	
565	    /**
566	     * Rejects an E.164 telephone whose national number does not have the exact length its country
567	     * calling code requires. The digits after the leading '+' are split into the longest matching
568	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
569	     * code is known and the national number's length differs from the required count the telephone is
570	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
571	     *
572	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
573	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
574	     */
575	    private void validateNationalNumberLength(String e164) {
576	        String digits = e164.substring(1);
577	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
578	            String countryCode = digits.substring(0, codeLength);
579	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
580	            if (requiredNationalLength != null) {
581	                int nationalLength = digits.length() - codeLength;
582	                if (nationalLength != requiredNationalLength) {
583	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
584	                }
585	                return;
586	            }
587	        }
588	    }
