590	    /**
591	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
592	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
593	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
594	     * stored and returned is the value lower-cased.
595	     *
596	     * @param email the raw email value from the request, or {@code null} when none was supplied
597	     * @return the lower-cased email, or {@code null} when no email was supplied
598	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
599	     *         its domain is on the disposable-domain blocklist
600	     */
601	    private String normalizeEmail(String email) {
602	        if (email == null || email.isBlank()) {
603	            return null;
604	        }
605	        if (!EMAIL_PATTERN.matcher(email).matches()) {
606	            throw new InvalidOwnerFieldsException(List.of("email"));
607	        }
608	        String normalized = email.toLowerCase(Locale.ROOT);
609	        String domain = normalized.substring(normalized.indexOf('@') + 1);
610	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
611	            throw new InvalidOwnerFieldsException(List.of("email"));
612	        }
613	        return normalized;
614	    }
