616	    /**
617	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
618	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
619	     * When present it must be exactly four digits and, when the owner's city maps to a known region
620	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
621	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
622	     * region accepts any four-digit postcode.
623	     *
624	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
625	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
626	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
627	     *         for the city's region
628	     */
629	    private void validatePostcode(String city, String postcode) {
630	        if (postcode == null || postcode.isBlank()) {
631	            return;
632	        }
633	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
634	            throw new InvalidOwnerFieldsException(List.of("postcode"));
635	        }
636	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
637	        if (range == null) {
638	            return;
639	        }
640	        int value = Integer.parseInt(postcode);
641	        if (value < range[0] || value > range[1]) {
642	            throw new InvalidOwnerFieldsException(List.of("postcode"));
643	        }
644	    }
