674	    /**
675	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
676	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
677	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
678	     * normalized form is what gets stored, returned and used for every address comparison (the
679	     * required-field check, household duplicate detection and the shared household id).
680	     *
681	     * @param address the raw address value from the request, or {@code null}
682	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
683	     */
684	    private String normalizeAddress(String address) {
685	        if (address == null) {
686	            return "";
687	        }
688	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
689	        if (collapsed.isEmpty()) {
690	            return "";
691	        }
692	        String[] tokens = collapsed.split(" ");
693	        for (int i = 0; i < tokens.length; i++) {
694	            switch (tokens[i]) {
695	                case "ST" -> tokens[i] = "STREET";
696	                case "RD" -> tokens[i] = "ROAD";
697	                case "AVE" -> tokens[i] = "AVENUE";
698	                default -> { }
699	            }
700	        }
701	        return String.join(" ", tokens);
702	    }
