704	    /**
705	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
706	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
707	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
708	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
709	     * so two members of one household with different telephones have different keys and are both
710	     * allowed; only an owner whose entire key is identical is a duplicate.
711	     *
712	     * @param owner the owner being created, with its telephone, email and householdId already resolved
713	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
714	     */
715	    private void rejectDuplicateIdentity(Owner owner) {
716	        String identityKey = owner.getIdentityKey();
717	        boolean inUse = this.clinicService.findAllOwners().stream()
718	            .filter(existing -> !existing.isDeleted())
719	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
720	        if (inUse) {
721	            throw new DuplicateOwnerIdentityException(identityKey);
722	        }
723	    }
