725	    /**
726	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
727	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
728	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
729	     * (its identity key differs) and is still created. When at least one soft match exists,
730	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
731	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
732	     * <p>
733	     * A declared household member - an owner that acknowledged sharing an existing household via
734	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
735	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
736	     *
737	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
738	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
739	     */
740	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
741	        if (declaredHouseholdMember) {
742	            owner.setPossibleDuplicate(false);
743	            return;
744	        }
745	        String lastName = normalizeHouseholdField(owner.getLastName());
746	        String postcode = owner.getPostcode();
747	        String telephone = owner.getTelephone();
748	        Owner match = null;
749	        if (postcode != null && !postcode.isBlank()) {
750	            match = this.clinicService.findAllOwners().stream()
751	                .filter(existing -> !existing.isDeleted())
752	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
753	                .filter(existing -> postcode.equals(existing.getPostcode()))
754	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
755	                .min(java.util.Comparator.comparing(Owner::getId))
756	                .orElse(null);
757	        }
758	        if (match != null) {
759	            owner.setPossibleDuplicate(true);
760	            owner.setPossibleDuplicateOf(match.getId());
761	        } else {
762	            owner.setPossibleDuplicate(false);
763	        }
764	    }
