796	    /**
797	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
798	     * last name and a postcode: the {@code householdId} is derived deterministically from the
799	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
800	     * owners with the same last name and postcode always resolve to the same identifier and belong to
801	     * the same household automatically - no acknowledgement is needed to create the link.
802	     * <p>
803	     * When the owner supplies a postcode its {@code householdId} is always assigned. If that household
804	     * already has at least one member, the create is a household duplicate: it is rejected with a 409
805	     * unless {@code sharesHousehold} is true, in which case the owner is created as a declared member
806	     * of that household. An owner with no postcode belongs to no household and is left without an
807	     * identifier.
808	     *
809	     * @param owner the owner being created
810	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
811	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
812	     *         {@code false}
813	     * @throws DuplicateOwnerHouseholdException when the household already exists and the create did not
814	     *         acknowledge it via {@code sharesHousehold}
815	     */
816	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
817	        String postcode = owner.getPostcode();
818	        if (postcode == null || postcode.isBlank()) {
819	            return false;
820	        }
821	        String lastName = normalizeHouseholdField(owner.getLastName());
822	        String householdId = generateHouseholdId(lastName, postcode);
823	        owner.setHouseholdId(householdId);
824	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
825	            .filter(existing -> !existing.isDeleted())
826	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
827	        if (!hasExistingMember) {
828	            return false;
829	        }
830	        if (!Boolean.TRUE.equals(sharesHousehold)) {
831	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), postcode);
832	        }
833	        return true;
834	    }
