836	    /**
837	     * Builds the stable identifier shared by the members of one household. It is derived purely from
838	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
839	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
840	     * two fields joined by a single '|'.
841	     *
842	     * @param normalizedLastName the household's last name, already normalized for comparison
843	     * @param postcode the household's postcode
844	     * @return the shared household identifier
845	     */
846	    private String generateHouseholdId(String normalizedLastName, String postcode) {
847	        String key = normalizedLastName + '|' + postcode;
848	        try {
849	            byte[] digest = MessageDigest.getInstance("SHA-256")
850	                .digest(key.getBytes(StandardCharsets.UTF_8));
851	            StringBuilder hex = new StringBuilder();
852	            for (byte b : digest) {
853	                hex.append(String.format("%02X", b));
854	                if (hex.length() >= 12) {
855	                    break;
856	                }
857	            }
858	            return hex.substring(0, 12);
859	        } catch (NoSuchAlgorithmException e) {
860	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
861	        }
862	    }
