864	    /**
865	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
866	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
867	     * the owner's normalized telephone and last name.
868	     *
869	     * @param input the string to digest
870	     * @param length the number of leading upper-case hex characters to return
871	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
872	     */
873	    private String sha256UpperHex(String input, int length) {
874	        try {
875	            byte[] digest = MessageDigest.getInstance("SHA-256")
876	                .digest(input.getBytes(StandardCharsets.UTF_8));
877	            StringBuilder hex = new StringBuilder();
878	            for (byte b : digest) {
879	                hex.append(String.format("%02X", b));
880	                if (hex.length() >= length) {
881	                    break;
882	                }
883	            }
884	            return hex.substring(0, length);
885	        } catch (NoSuchAlgorithmException e) {
886	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
887	        }
888	    }
889	
890	    /**
891	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
892	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
893	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
894	     * expands common abbreviations.
895	     *
896	     * @param value the raw last name, or {@code null}
897	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
898	     */
899	    private String normalizeHouseholdField(String value) {
900	        if (value == null) {
901	            return "";
902	        }
903	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
904	    }
905	}
